-- Debugging via nvim-dap + delve.
--
-- nvim-dap-go registers the `delve` adapter and two configurations (`Launch`,
-- `Attach`). The `dlv` binary comes from mason.
--
-- Keymaps live under <leader>D: the <leader>d namespace is already taken by
-- diagnostics (<leader>d), diffview (<leader>dv, <leader>dc) and rename.

local dap = require("dap")
local dapui = require("dapui")

require("dapui").setup()

require("dap-go").setup({
  delve = {
    path = "dlv",
    initialize_timeout_sec = 20,
  },
  -- Reuse the standard test configurations generated by nvim-dap-go.
  dap_configurations = {
    {
      type = "go",
      name = "Attach remote",
      mode = "remote",
      request = "attach",
    },
  },
})

-- Open/close the UI together with the debug session.
dap.listeners.after.event_initialized["dapui"] = function()
  dapui.open()
end
dap.listeners.before.event_terminated["dapui"] = function()
  dapui.close()
end
dap.listeners.before.event_exited["dapui"] = function()
  dapui.close()
end

-- Breakpoint signs.
vim.fn.sign_define("DapBreakpoint", { text = "", texthl = "DiagnosticError" })
vim.fn.sign_define("DapBreakpointCondition", { text = "", texthl = "DiagnosticWarn" })
vim.fn.sign_define("DapLogPoint", { text = "", texthl = "DiagnosticInfo" })
vim.fn.sign_define("DapStopped", { text = "▶", texthl = "DiagnosticInfo", linehl = "Visual" })

local function map(lhs, rhs, desc)
  vim.keymap.set("n", lhs, rhs, { noremap = true, silent = true, desc = desc })
end

map("<leader>Db", function()
  dap.toggle_breakpoint()
end, "Debug: toggle breakpoint")
map("<leader>DB", function()
  dap.set_breakpoint(vim.fn.input("Breakpoint condition: "))
end, "Debug: conditional breakpoint")
map("<leader>Dl", function()
  dap.set_breakpoint(nil, nil, vim.fn.input("Log point message: "))
end, "Debug: log point")
map("<leader>Dc", function()
  dap.continue()
end, "Debug: continue / start")
map("<leader>Di", function()
  dap.step_into()
end, "Debug: step into")
map("<leader>Do", function()
  dap.step_over()
end, "Debug: step over")
map("<leader>DO", function()
  dap.step_out()
end, "Debug: step out")
map("<leader>Dr", function()
  dap.restart()
end, "Debug: restart")
map("<leader>Dx", function()
  dap.terminate()
end, "Debug: terminate")
map("<leader>Du", function()
  dapui.toggle()
end, "Debug: toggle UI")
map("<leader>De", function()
  dapui.eval()
end, "Debug: eval expression")
map("<leader>Dt", function()
  require("dap-go").debug_test()
end, "Debug: nearest test function")
map("<leader>DT", function()
  require("dap-go").debug_last_test()
end, "Debug: last test function")
